import sys

def main():
    args = sys.argv[1:]
    count_lines = False
    count_words = False
    count_chars = False
    has_flags = False

    file_arg = None

    i = 0
    while i < len(args):
        arg = args[i]
        if arg.startswith('-') and arg != '-':
            has_flags = True
            for ch in arg[1:]:
                if ch == 'l':
                    count_lines = True
                elif ch == 'w':
                    count_words = True
                elif ch == 'c':
                    count_chars = True
                else:
                    pass  # ignore unknown flags
        else:
            file_arg = arg
        i += 1

    if not has_flags:
        count_lines = True
        count_words = True
        count_chars = True

    if file_arg is None or file_arg == '-':
        data = sys.stdin.buffer.read()
    else:
        with open(file_arg, 'rb') as f:
            data = f.read()

    num_chars = len(data)
    num_words = len(data.split())
    # Count lines: split by b'\n'; a final line without newline still counts
    num_lines = data.count(b'\n')
    if data and not data.endswith(b'\n'):
        num_lines += 1

    results = []
    if count_lines:
        results.append(str(num_lines))
    if count_words:
        results.append(str(num_words))
    if count_chars:
        results.append(str(num_chars))

    print(' '.join(results))

if __name__ == '__main__':
    main()
